-- Generated by scripts/upload-lesson-videos.mjs (prompts/15). Do not edit by hand:
-- change supabase/seeds/source/lesson-videos.json and run `npm run upload:lesson-videos`.
-- Points each chapter's lessons at its clip in the private R2 bucket and ends their notes
-- with the clip's credit. Safe to re-run.

-- Chapters no longer in the list go back to their placeholder video_url.
update public.lesson_contents
set video_key = null,
    body = regexp_replace(body, E'\n\n\\*Video: [^\n]*\\*$', '')
where video_key like 'clips/%' and video_key not in ('clips/advanced-animations-1.mp4', 'clips/advanced-animations-3.mp4', 'clips/data-analysis-pandas-1.mp4', 'clips/data-analysis-pandas-2.mp4', 'clips/data-analysis-pandas-3.mp4', 'clips/data-analysis-pandas-4.mp4', 'clips/design-systems-1.mp4', 'clips/python-for-everyone-1.mp4', 'clips/python-for-everyone-3.mp4', 'clips/react-native-basics-1.mp4', 'clips/react-native-basics-2.mp4', 'clips/react-native-basics-3.mp4', 'clips/ui-design-fundamentals-1.mp4', 'clips/ui-design-fundamentals-2.mp4', 'clips/ui-design-fundamentals-3.mp4');

-- advanced-animations / chapter 1 (Motion principles): File:The CSS-Podcast – 090 – Scroll-driven animations.webm, CC BY 3.0
update public.lesson_contents lc
set video_key = 'clips/advanced-animations-1.mp4',
    body = regexp_replace(coalesce(lc.body, ''), E'\n\n\\*Video: [^\n]*\\*$', '') || E'\n\n' || '*Video: "The CSS-Podcast – 090 – Scroll-driven animations" by Chrome for Developers, CC BY 3.0, via Wikimedia Commons.*'
from public.lessons l
join public.chapters ch on ch.id = l.chapter_id
join public.courses c on c.id = ch.course_id
where lc.lesson_id = l.id and c.slug = 'advanced-animations' and ch.position = 1;

